#include <map>
#include <stddef.h>

class stringx
{
public:
  stringx( const char*, int = -1 );
  stringx( const stringx& );
  ~stringx();
  bool operator<( const stringx& b ) const;

  char* data;
  int capacity;
  int length;
};

inline bool stringx::operator<( const stringx& b ) const
{
  int n = length < b.length ? length : b.length;
  for ( int i = 0; i < n; ++i )
  {
    if ( data[i] < b.data[i] )
      return true;
    if ( b.data[i] < data[i] )
      return false;
  }
  return length < b.length;
}

class entity {};

class entity_id
{
public:
  static const entity_id& make_unique_id();
};

class entity_pool
{
public:
  entity_pool();
  void add( entity* );
  entity* acquire( unsigned int );
};

class world_dynamics_system
{
public:
  entity* add_beam( const entity_id&, unsigned int );
};

extern world_dynamics_system* g_world_ptr;
void* operator new( size_t, unsigned int, const char*, int );

#define NEW new( 0, __FILE__, __LINE__ )

class entity_pool_set
{
public:
  typedef std::map<stringx, entity_pool*> set_t;
  set_t entity_pools;
  entity* acquire_beam( unsigned int flags );
};

entity* entity_pool_set::acquire_beam( unsigned int flags )
{
  // find an entry corresponding to the given name
  typedef entity_pool* ep_ptr_t;
  ep_ptr_t& epool = entity_pools["_BEAM"];
  if ( epool == NULL )
  {
    // need to construct the base entity
    entity* base = g_world_ptr->add_beam( entity_id::make_unique_id(), flags );
    epool = NEW entity_pool();
    epool->add( base );
    return base;
  }
  else
  {
    // acquire an entity from the given pool
    return epool->acquire( flags );
  }
}
